const D = { energy:.6, scale:1, density:.5, speed:1, hue:44, x:.5, y:.16, drop:.55, anno:.6, style:'film', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const lp = (a,b,s) => a+(b-a)*s;
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const AL = cl(P.alpha,20,100)/100;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const anno = cl(P.anno,0,1);
const NRG = cl(P.energy,0,1);

function pal(){
  if (sty==='cyanotype') return { line:[200,6,99], body:[208,52,38], dark:[214,70,15], ctr:[196,38,80], anno:[200,12,92], hatch:[204,44,58], hot:[46,70,98], rope:[198,20,88], add:false };
  if (sty==='engraving') return { line:[28,40,10], body:[36,14,64], dark:[32,26,32], ctr:[8,64,42], anno:[28,42,14], hatch:[30,30,26], hot:[6,74,44], rope:[30,34,22], add:false };
  if (sty==='ghost')     return { line:[H,26,98], body:[H,62,28], dark:[H,66,11], ctr:[12,72,60], anno:[H,16,86], hatch:[H,44,52], hot:[46,74,100], rope:[H,20,96], add:true };
  if (sty==='schematic') return { line:[178,64,94], body:[190,50,20], dark:[196,44,9], ctr:[10,72,68], anno:[52,56,88], hatch:[186,42,44], hot:[340,74,96], rope:[178,30,94], add:false };
  return { line:[H,8,93], body:[H,22,40], dark:[H,30,15], ctr:[10,66,62], anno:[H,8,88], hatch:[H,14,56], hot:[H+8,74,96], rope:[H,10,86], add:false };
}
const C = pal();
const hw = q => ((q%360)+360)%360;
const sc = (c,a) => { stroke(hw(c[0]), c[1], c[2], a*AL); };
const fc = (c,a) => { fill(hw(c[0]), c[1], c[2], a*AL); };
const schem = (sty==='schematic');

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .06); S.pt = K.t;
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.42+.58*NRG)*(.55+.5*K.intensity) + S.bs*.3;

// ---- rig geometry ------------------------------------------------------------
const SCA = cl(P.scale,.4,1.9);
const SPAN = width*.86*cl(SCA,.5,1.35);
const gy = cl(P.y,.04,.55)*height;
const gcx = cl(P.x,.2,.8)*width;
const gx0 = gcx - SPAN/2, gx1 = gcx + SPAN/2;
const GD = u*.052*SCA;                       // girder depth

// ---- trolley traverse: analytic ease so velocity AND acceleration are exact --
const NW = Math.round(3 + cl(P.density,0,1)*5);
if (S.wk !== sd+'|'+NW){
  S.wk = sd+'|'+NW; S.wp = [];
  for (let i=0;i<NW;i++) S.wp.push({ p: .10 + fr(i*3.7+2)*.80, h: .30 + fr(i*5.3+7)*.62, dw: .16 + fr(i*7.1+11)*.26 });
}
const WP = S.wp || [{p:.5,h:.5,dw:.2}];
const wob = 1 + .20*Math.sin(K.t*.127) + .12*Math.sin(K.t*.311+1.4) + .07*Math.sin(K.t*.743+2.7);
const prate = P.speed * (.10 + .17*NRG) * wob * (.6+.7*K.intensity);
S.tg = (S.tg||0) + dt*prate;
const seg = Math.floor(S.tg) % WP.length;
const rawF = S.tg - Math.floor(S.tg);
const w0 = WP[seg], w1 = WP[(seg+1)%WP.length];
const dw = w0.dw;
const mf = cl((rawF - dw)/Math.max(.05, 1-dw), 0, 1);
const es = mf*mf*(3-2*mf);
const trX = lp(gx0 + SPAN*w0.p, gx0 + SPAN*w1.p, es);
// analytic derivatives of the smoothstep programme -> honest trolley dynamics
const dEs = 6*mf*(1-mf), ddEs = 6-12*mf;
const dfdt = (mf>0 && mf<1) ? prate/Math.max(.05, 1-dw) : 0;
const dX = (gx0+SPAN*w1.p - (gx0+SPAN*w0.p));
const trA = dX * ddEs * dfdt * dfdt;          // trolley acceleration, px/s^2

// ---- hoist -------------------------------------------------------------------
const maxDrop = (height - gy) * cl(P.drop,.15,1) * .92;
const ropeL = Math.max(u*.05, lp(w0.h, w1.h, es) * maxDrop);

// ---- the load is a REAL pendulum driven by the trolley's acceleration --------
if (S.th == null){ S.th = 0; S.thd = 0; }
{
  const g = u*1.8;
  const sub = cl(Math.round(dt/(1/240)), 1, 6), h2 = dt/sub;
  for (let i=0;i<sub;i++){
    const acc = -(g/ropeL)*Math.sin(S.th) - .80*S.thd - (trA/ropeL)*Math.cos(S.th);
    S.thd += acc*h2;
    S.th  += S.thd*h2;
    if (S.th > 1.05){ S.th = 1.05; S.thd = 0; }
    if (S.th < -1.05){ S.th = -1.05; S.thd = 0; }
    if (!isFinite(S.th) || !isFinite(S.thd)){ S.th = 0; S.thd = 0; }
  }
}
const th = S.th;
const blkX = trX + Math.sin(th)*ropeL, blkY = gy + GD*.5 + Math.cos(th)*ropeL;

// ---- helpers -----------------------------------------------------------------
const LW = Math.max(1, u*.0026*(.6+.7*NRG))*cl(SCA,.6,1.5);
// 45-deg section hatch, analytically clipped to the rect (t0/t1 along the diagonal)
function hatchRect(x,y,w2,h2,a){
  sc(C.hatch, a); strokeWeight(Math.max(.4,u*.0007));
  const sp = Math.max(u*.009, Math.min(w2,h2)*.22);
  for (let o=-h2; o<w2; o+=sp){
    const t0 = Math.max(0, -o), t1 = Math.min(h2, w2-o);
    if (t1 <= t0) continue;
    line(x+o+t0, y+t0, x+o+t1, y+t1);
  }
}
function lattice(x0,y0,x1,y1,d,n){
  sc(C.line, C.add?52:88); strokeWeight(LW);
  line(x0,y0,x1,y1); line(x0,y0+d,x1,y1+d);
  sc(C.line, C.add?38:64); strokeWeight(LW*.55);
  for (let i=0;i<n;i++){
    const a0=x0+(x1-x0)*(i/n), a1=x0+(x1-x0)*((i+1)/n);
    line(a0,y0, a1,y0+d); line(a1,y0, a0,y0+d);
    line(a0,y0, a0,y0+d);
  }
}

if (C.add) blendMode(ADD);

// ---- runway rails + end trucks ----------------------------------------------
if (!schem){
  sc(C.dark, C.add?30:80); strokeWeight(LW*2.4);
  line(0, gy - GD*.72, width, gy - GD*.72);
  sc(C.line, 86); strokeWeight(LW*.8);
  line(0, gy - GD*.95, width, gy - GD*.95);
  for (const ex of [gx0, gx1]){
    noStroke(); fc(C.body, C.add?26:92);
    rect(ex - GD*.55, gy - GD*.62, GD*1.1, GD*1.25);
    noFill(); sc(C.line, 92); strokeWeight(LW); rect(ex - GD*.55, gy - GD*.62, GD*1.1, GD*1.25);
    for (const wx of [-1,1]){
      noStroke(); fc(C.dark, C.add?22:92); ellipse(ex + wx*GD*.32, gy - GD*.72, GD*.42, GD*.42);
      noFill(); sc(C.line, 88); strokeWeight(LW*.6); ellipse(ex + wx*GD*.32, gy - GD*.72, GD*.42, GD*.42);
    }
  }
}

// ---- bridge girder -----------------------------------------------------------
if (schem){
  sc(C.line, 88); strokeWeight(LW*1.2); line(gx0, gy, gx1, gy);
  for (const ex of [gx0,gx1]){ sc(C.ctr,70); strokeWeight(Math.max(.4,u*.0008));
    for (let i=-2;i<=2;i++) line(ex+i*GD*.2, gy, ex+i*GD*.2-GD*.16, gy-GD*.3); }
} else {
  lattice(gx0, gy, gx1, gy, GD, Math.round(10 + cl(P.density,0,1)*14));
}

// ---- festoon: constant-length cable loops that bunch as the trolley closes ---
if (!schem && anno > .1){
  const fx0 = gx0 + GD*.5;
  const NF = Math.round(5 + cl(P.density,0,1)*6);
  const spanF = Math.abs(trX - fx0);
  const sp = spanF/NF;
  const maxSp = (SPAN*.9)/NF;
  const sag = GD*.28 + GD*1.05*(1 - cl(sp/Math.max(1e-3,maxSp),0,1));
  sc(C.rope, C.add?40:70); strokeWeight(Math.max(.6,LW*.42));
  for (let i=0;i<NF;i++){
    const a0 = lp(fx0, trX, i/NF), a1 = lp(fx0, trX, (i+1)/NF);
    noFill(); beginShape();
    for (let s=0;s<=6;s++){ const t=s/6; vertex(lp(a0,a1,t), gy + GD*1.05 + 4*sag*t*(1-t)); }
    endShape();
    sc(C.line, 62); strokeWeight(Math.max(.4,LW*.3));
    line(a0, gy+GD, a0, gy+GD*1.05+GD*.12);
    sc(C.rope, C.add?40:70); strokeWeight(Math.max(.6,LW*.42));
  }
}

// ---- trolley -----------------------------------------------------------------
const TW = GD*1.5;
if (!schem){
  noStroke(); fc(C.body, C.add?28:94);
  rect(trX - TW*.5, gy - GD*.30, TW, GD*.92);
  hatchRect(trX - TW*.5, gy - GD*.30, TW, GD*.92, 40);
  noFill(); sc(C.line, 96); strokeWeight(LW); rect(trX - TW*.5, gy - GD*.30, TW, GD*.92);
  // hoist drum + the rope wrapping it as the load rises
  const dr = GD*.34;
  noStroke(); fc(C.dark, C.add?24:92); ellipse(trX, gy + GD*.16, dr*2, dr*2);
  noFill(); sc(C.line, 90); strokeWeight(LW*.7); ellipse(trX, gy + GD*.16, dr*2, dr*2);
  sc(C.line, 58); strokeWeight(Math.max(.4,u*.0007));
  const wrap = -ropeL/Math.max(1e-3,maxDrop)*9;
  for (let i=0;i<7;i++){ const a=wrap + i*0.9; line(trX+Math.cos(a)*dr*.35, gy+GD*.16+Math.sin(a)*dr*.35, trX+Math.cos(a)*dr*.92, gy+GD*.16+Math.sin(a)*dr*.92); }
  for (const wx of [-1,1]){
    noStroke(); fc(C.dark, C.add?20:92); ellipse(trX + wx*TW*.32, gy, GD*.30, GD*.30);
    noFill(); sc(C.line, 80); strokeWeight(LW*.5); ellipse(trX + wx*TW*.32, gy, GD*.30, GD*.30);
  }
}

// ---- 2-fall reeving: the ropes really do angle as the block swings -----------
{
  const sh = GD*.30;
  sc(C.rope, C.add?52:86); strokeWeight(Math.max(.7, LW*.34));
  for (const s2 of [-1,1]){
    line(trX + s2*sh, gy + GD*.4, blkX + s2*sh*.5, blkY - GD*.28);
  }
}

// ---- load block, hook, and the load ------------------------------------------
{
  const bw = GD*.9, bh = GD*.55;
  if (!schem){
    noStroke(); fc(C.body, C.add?30:96); rect(blkX - bw*.5, blkY - GD*.28, bw, bh);
    noFill(); sc(C.line, 96); strokeWeight(LW*.85); rect(blkX - bw*.5, blkY - GD*.28, bw, bh);
    for (const s2 of [-1,1]){ sc(C.line, 70); strokeWeight(LW*.5); ellipse(blkX + s2*bw*.24, blkY - GD*.28 + bh*.5, bh*.5, bh*.5); }
    // hook
    sc(C.line, 96); strokeWeight(LW*.9); noFill();
    const hkY = blkY - GD*.28 + bh;
    line(blkX, hkY, blkX, hkY + GD*.22);
    arc(blkX, hkY + GD*.40, GD*.34, GD*.40, -Math.PI*.85, Math.PI*.72);
  } else {
    noStroke(); fc(C.hot, 94); ellipse(blkX, blkY, GD*.34, GD*.34);
  }
  // the load: a hatched blank slung under the hook
  const ls = GD*(1.05 + .5*cl(P.density,0,1));
  const ly = blkY + GD*.72 + ls*.5;
  if (!schem){
    sc(C.rope, 80); strokeWeight(Math.max(.5,LW*.30));
    line(blkX, blkY + GD*.52, blkX - ls*.42, ly - ls*.5);
    line(blkX, blkY + GD*.52, blkX + ls*.42, ly - ls*.5);
    noStroke(); fc(C.body, C.add?26:94); rect(blkX - ls*.62, ly - ls*.5, ls*1.24, ls);
    hatchRect(blkX - ls*.62, ly - ls*.5, ls*1.24, ls, 46);
    noFill(); sc(C.line, 96); strokeWeight(LW); rect(blkX - ls*.62, ly - ls*.5, ls*1.24, ls);
    sc(C.line, 60); strokeWeight(LW*.5);
    line(blkX - ls*.62, ly - ls*.18, blkX + ls*.62, ly - ls*.18);
    line(blkX - ls*.62, ly + ls*.20, blkX + ls*.62, ly + ls*.20);
  } else {
    // free-body diagram: weight down, rope tension along the fall, sway arc
    const vs = u*.075;
    const arrow = (ax2,ay2,bx2,by2,col) => { const an=Math.atan2(by2-ay2,bx2-ax2), hd=u*.011;
      sc(col, 92); strokeWeight(Math.max(.9,u*.0020)); line(ax2,ay2,bx2,by2);
      line(bx2,by2, bx2-Math.cos(an-.4)*hd, by2-Math.sin(an-.4)*hd);
      line(bx2,by2, bx2-Math.cos(an+.4)*hd, by2-Math.sin(an+.4)*hd); };
    arrow(blkX, blkY, blkX, blkY+vs, C.hot);
    arrow(blkX, blkY, blkX - Math.sin(th)*vs*1.15, blkY - Math.cos(th)*vs*1.15, C.line);
    sc(C.ctr, 70); strokeWeight(Math.max(.5,u*.0010)); noFill();
    line(trX, gy, trX, gy + ropeL*1.1);
    const aw = Math.max(.02, Math.abs(th));
    arc(trX, gy + GD*.5, ropeL*.9, ropeL*.9, Math.PI/2 - aw, Math.PI/2 + aw);
  }
}
blendMode(BLEND);

// ---- annotation --------------------------------------------------------------
if (anno > .12){
  textFont('monospace'); noStroke(); textSize(Math.max(6, Math.min(u*.0125, GD*.34)));
  // capacity on the girder
  textAlign(CENTER, CENTER); fc(C.anno, 84);
  text('SWL '+(8 + Math.round(cl(P.density,0,1)*42))+' t', gcx, gy + GD*.5);
  // live sway + hoist readout on a leader off the block
  if (anno > .35){
    const lx = blkX + GD*1.5, ly2 = blkY - GD*1.1;
    sc(C.anno, 50+26*anno); strokeWeight(Math.max(.4,u*.0007));
    line(blkX + GD*.4, blkY - GD*.2, lx, ly2); line(lx, ly2, lx + u*.030, ly2);
    noStroke(); fc(C.anno, 92); textAlign(LEFT, BOTTOM);
    const ts = Math.max(6, Math.min(u*.0115, GD*.30));
    textSize(ts);
    text('SWAY '+(th*57.2958).toFixed(1)+' deg', lx + u*.034, ly2 - u*.002);
    text('HOIST '+(ropeL/Math.max(1e-3,maxDrop)*18).toFixed(2)+' m', lx + u*.034, ly2 - u*.002 + ts*1.35);
    text(Math.abs(trA) > u*.4 ? 'TRAVERSE - ACCEL' : (dfdt>0 ? 'TRAVERSE' : 'HOLD'), lx + u*.034, ly2 - u*.002 + ts*2.7);
  }
  // span dimension under the girder
  if (anno > .5){
    const dy2 = gy + GD*2.4;
    sc(C.ctr, 62); strokeWeight(Math.max(.4,u*.0008));
    line(gx0, gy+GD*1.2, gx0, dy2+u*.010); line(gx1, gy+GD*1.2, gx1, dy2+u*.010);
    line(gx0, dy2, gx1, dy2);
    const ar = u*.010;
    line(gx0,dy2, gx0+ar,dy2-ar*.4); line(gx0,dy2, gx0+ar,dy2+ar*.4);
    line(gx1,dy2, gx1-ar,dy2-ar*.4); line(gx1,dy2, gx1-ar,dy2+ar*.4);
    noStroke(); fc(C.anno, 86); textAlign(CENTER, BOTTOM);
    text((SPAN/u*22).toFixed(1)+' m SPAN', gcx, dy2 - u*.004);
  }
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
